WITH Src AS (SELECT *, ARRAY_JOIN(tags, '|') tags_text FROM products WHERE brand = 'Umbrella' OR stock_qty <= 368), brand_summary AS (SELECT brand, CASE WHEN cost >= 660 THEN 'high' WHEN cost >= 220 THEN 'mid' ELSE 'low' END cost_bucket, ROUND(STDDEV(cost), 2) stddev_cost FROM Src GROUP BY brand, CASE WHEN cost >= 660 THEN 'high' WHEN cost >= 220 THEN 'mid' ELSE 'low' END) SELECT brand, cost_bucket, stddev_cost FROM brand_summary ORDER BY stddev_cost, brand DESC, cost_bucket LIMIT 50;
